import path from "node:path";
import { fileURLToPath } from "node:url";

import { createDevControlsHandlers, createDevControlsTrust } from "../electron-main/dev/dev-controls-edge.js";
import { isDevControlsEnabled } from "../electron-main/dev/dev-controls-gate.js";
import {
  createDevControlsWindowRuntime,
  fetchGatewayOffline,
  fetchTheme,
  getAttachProdBoxStatus,
  openDevControlsWindow,
  postDevControl,
  writeAttachProdBoxPrefs,
  type DevBrowserWindow,
} from "../electron-main/dev/dev-controls-window.js";
import { createOnePasswordCliDevController } from "../electron-main/onepassword/onepassword-cli-dev-controls.js";
import { installProcessCrashGuards } from "../host/process-crash-guard.js";
import { DEV_CONTROLS_METHOD_TABLE } from "../shared/rpc/dev-controls.js";

export interface DevControlsApp {
  readonly isPackaged: boolean;
  quit(): void;
  requestSingleInstanceLock(): boolean;
  on(event: "second-instance" | "window-all-closed", listener: () => void): void;
  whenReady(): Promise<unknown>;
}

export function startElectronDevControls(app: DevControlsApp, deps: {
  readonly openDevControlsWindow: () => void;
  readonly serveDevControlsEdge: () => void;
  readonly installCrashGuards?: typeof installProcessCrashGuards;
}): { readonly started: boolean } {
  (deps.installCrashGuards ?? installProcessCrashGuards)({ scope: "sand-dev-controls" });
  if (!isDevControlsEnabled({ isPackaged: app.isPackaged })) {
    app.quit();
    return { started: false };
  }
  if (!app.requestSingleInstanceLock()) {
    app.quit();
    return { started: false };
  }
  app.on("second-instance", deps.openDevControlsWindow);
  void app.whenReady().then(() => {
    deps.serveDevControlsEdge();
    deps.openDevControlsWindow();
  });
  app.on("window-all-closed", () => app.quit());
  return { started: true };
}

interface DevControlsWebContents {}
interface ElectronBrowserWindow extends DevBrowserWindow { readonly webContents: DevControlsWebContents }
interface DevControlsIpcMain {
  handle(channel: string, listener: (event: { readonly sender: DevControlsWebContents }, payload: unknown) => Promise<unknown>): void;
  removeHandler(channel: string): void;
}

export interface ElectronDevControlsRuntime {
  readonly app: DevControlsApp;
  readonly screen: { getPrimaryDisplay(): { workArea: { x: number; y: number; width: number; height: number } } };
  readonly ipcMain: DevControlsIpcMain;
  readonly shell: { openExternal(url: string): Promise<unknown> };
  readonly BrowserWindow: new (options: Record<string, unknown>) => ElectronBrowserWindow;
}

type DevControlsHandlerSet = ReturnType<typeof createDevControlsHandlers>;

export function serveDevControlsRpcEdge(options: {
  readonly ipcMain: DevControlsIpcMain;
  readonly handlers: DevControlsHandlerSet;
  readonly isPanelSender: (sender: DevControlsWebContents) => boolean;
}): { dispose(): void } {
  const trust = createDevControlsTrust().devControlsPanel;
  const channels: string[] = [];
  for (const method of Object.keys(DEV_CONTROLS_METHOD_TABLE) as Array<keyof typeof DEV_CONTROLS_METHOD_TABLE>) {
    const handler = options.handlers[method];
    if (handler == null) throw new Error(`serveEdge(dev-controls): missing handler ${method}`);
    const channel = `sand-rpc:dev-controls:m:${method}`;
    channels.push(channel);
    options.ipcMain.handle(channel, async (event, payload) => {
      if (!trust.test({ isDevControlsPanel: options.isPanelSender(event.sender) })) {
        return { ok: false, failure: { code: "edge/untrusted-sender", detail: trust.denial } };
      }
      try {
        return { ok: true, value: await handler.run(payload as never) };
      } catch (error) {
        return { ok: false, failure: { code: "edge/handler-failed", detail: error instanceof Error ? error.message : String(error) } };
      }
    });
  }
  let disposed = false;
  return {
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const channel of channels) options.ipcMain.removeHandler(channel);
    },
  };
}

export function resolveElectronDevControlsProjectDir(moduleUrl = import.meta.url): string {
  return path.resolve(path.dirname(fileURLToPath(moduleUrl)), "..", "..");
}

export function startElectronDevControlsEntrypoint(
  electron: ElectronDevControlsRuntime,
  options: { readonly moduleUrl?: string; readonly env?: NodeJS.ProcessEnv } = {},
): { readonly started: boolean } {
  const env = options.env ?? process.env;
  const moduleDirectory = path.dirname(fileURLToPath(options.moduleUrl ?? import.meta.url));
  const projectDir = resolveElectronDevControlsProjectDir(options.moduleUrl ?? import.meta.url);
  const windowRuntime = createDevControlsWindowRuntime({ projectDir, env });
  const onePasswordCli = createOnePasswordCliDevController({ projectDir });
  let panelWindow: ElectronBrowserWindow | undefined;
  const open = (): void => openDevControlsWindow({
    electron: {
      screen: electron.screen,
      createBrowserWindow(windowOptions) {
        panelWindow = new electron.BrowserWindow(windowOptions);
        return panelWindow;
      },
    },
    ...(env.VITE_DEV_SERVER_URL === undefined ? {} : { devServerUrl: env.VITE_DEV_SERVER_URL }),
    preloadPath: path.join(moduleDirectory, "..", "electron-preload", "preload-dev-controls.cjs"),
  });
  const serve = (): void => {
    const handlers = createDevControlsHandlers({
      postControl: (pathname) => postDevControl(pathname),
      fetchTheme: (search) => fetchTheme(search),
      fetchGatewayOffline: (search) => fetchGatewayOffline(search),
      onePasswordCli,
      getAttachProdBoxStatus: () => getAttachProdBoxStatus(),
      writeAttachProdBoxPrefs: (enabled) => writeAttachProdBoxPrefs(enabled),
      collectBoxStatus: () => windowRuntime.collectBoxStatus(),
      collectBoxHealth: () => windowRuntime.collectBoxHealth(),
      runDevBoxScript: (command) => windowRuntime.runDevBoxScript(command),
      pokeHostUpgrade: () => windowRuntime.pokeHostUpgrade(),
      tailBoxLogs: () => windowRuntime.tailBoxLogs(),
      nukeBox: () => windowRuntime.nukeBox(),
      openBoxDesktop: () => windowRuntime.openBoxDesktop((url) => electron.shell.openExternal(url)),
      collectBoxStoreStatus: () => windowRuntime.collectBoxStoreStatus(),
      snapshotBoxStoreNow: () => windowRuntime.snapshotBoxStoreNow(),
      boxStoreLogs: () => windowRuntime.boxStoreLogs(),
    });
    serveDevControlsRpcEdge({
      ipcMain: electron.ipcMain,
      handlers,
      isPanelSender: (sender) => panelWindow != null && !panelWindow.isDestroyed() && sender === panelWindow.webContents,
    });
  };
  return startElectronDevControls(electron.app, { openDevControlsWindow: open, serveDevControlsEdge: serve });
}

export function loadElectronDevControlsRuntime(
  requireModule: (id: string) => unknown = createRequire(import.meta.url),
): ElectronDevControlsRuntime {
  const runtime = requireModule("electron") as Partial<ElectronDevControlsRuntime>;
  if (runtime.app == null || runtime.screen == null || runtime.ipcMain == null || runtime.shell == null || runtime.BrowserWindow == null) {
    throw new Error("electron dev-controls bindings are unavailable");
  }
  return runtime as ElectronDevControlsRuntime;
}

if ((process as NodeJS.Process & { readonly type?: string }).type === "browser") {
  startElectronDevControlsEntrypoint(loadElectronDevControlsRuntime());
}

/**
 * End-to-end validation of stale-trace freshness flagging in the Android
 * native-profiler analyze report (PR #340, behavior 2).
 *
 * This drives the REAL pipeline → render path. Nothing in the freshness chain
 * is mocked: `analyzeNativeProfilerAndroid` calls `formatTraceFreshness(
 * api.wallClockStartMs, Date.now())` for real, threads the result into
 * `renderNativeProfilerReport`, and the renderer emits (or omits) the warning
 * line. Only the Perfetto WASM engine boundary (`ensureTraceProcessorReady` +
 * `runTpQuery`) is stubbed — exactly as native-profiler-analyze-failure.test.ts
 * does — so a minimal/empty `.pftrace` fixture is tolerated and we get a clean
 * "All clear" body to hang the freshness header off.
 *
 * Two layers are exercised:
 *   1. Persistence round-trip: the real `.pftrace.metadata.json` sidecar shape
 *      is written, then restored by the REAL `profilerLoadTool.execute`, which
 *      sets `api.wallClockStartMs`. The age matrix flows wallClockStartMs →
 *      sidecar → profiler-load → analyze → rendered freshness line.
 *   2. The freshness line in the final report is asserted AND console.logged so
 *      the real output is observable in the test run.
 *
 * Age matrix (relative to a frozen "now"): fresh (−2 min), boundary (−30 min),
 * stale minutes (−45 min), hours (−3 h), days (−2 d), and the unknown/guarded
 * cases (missing field, NaN, Infinity).
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { ArtifactStore } from "@argent/registry";
import { mkdtemp, rm, writeFile, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

// Stub ONLY the Perfetto engine boundary. The pipeline, render, and the entire
// freshness chain run for real against the empty .pftrace fixture.
vi.mock("../../src/utils/android-profiler/pipeline/run-tp", () => ({
  runTpQuery: vi.fn(),
}));
vi.mock("@argent/native-devtools-android", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@argent/native-devtools-android")>();
  return {
    ...actual,
    ensureTraceProcessorReady: vi.fn().mockResolvedValue(undefined),
  };
});

import { runTpQuery } from "../../src/utils/android-profiler/pipeline/run-tp";
import {
  nativeProfilerSessionBlueprint,
  type NativeProfilerSessionApi,
} from "../../src/blueprints/native-profiler-session";
import { profilerLoadTool } from "../../src/tools/profiler/query/profiler-load";
import { nativeProfilerAnalyzeTool } from "../../src/tools/profiler/native-profiler/native-profiler-analyze";
import { __primeDepCacheForTests, __resetDepCacheForTests } from "../../src/utils/check-deps";
import {
  writeAndroidNativeProfilerMetadata,
  readAndroidNativeProfilerMetadata,
  androidNativeProfilerMetadataPath,
} from "../../src/utils/android-profiler/session-metadata";
import { RECORDING_CAP_MS } from "../../src/utils/profiler-shared/types";
import { redirectTmpdir } from "../helpers/tmpdir-env";

const runTpQueryMock = runTpQuery as unknown as ReturnType<typeof vi.fn>;
const MIN = 60_000;
const SESSION_ID = "20260101-000000";
const SERIAL = "emulator-5554";

// Route the stubbed engine so the real pipeline produces a clean ("All clear")
// report: one CPU row whose leaf_function is null (the aggregator drops it, so
// bottlenecksTotal === 0 without tripping the "no CPU samples" fallback that a
// pair of empty results would). Mirrors the happy-path stub in
// native-profiler-analyze-failure.test.ts.
function routeCleanTrace(): void {
  runTpQueryMock.mockImplementation(async (opts: { query: string }) => {
    switch (opts.query) {
      case "trace-bounds.sql":
        return [{ start_ts: 0 }];
      case "cpu-hotspots.sql":
        return [
          {
            thread_name: "main",
            is_main_thread: 1,
            leaf_function: null,
            sample_count: 0,
            first_ts_ns: 0,
            last_ts_ns: 0,
            burst_windows: null,
            total_samples: 0,
          },
        ];
      case "ui-hangs.sql":
      case "memory-rss.sql":
        return [];
      default:
        throw new Error(`unexpected query ${opts.query}`);
    }
  });
}

async function buildAndroidSession(): Promise<NativeProfilerSessionApi> {
  const device = { id: SERIAL, platform: "android" as const, kind: "emulator" as const };
  const instance = await nativeProfilerSessionBlueprint.factory({}, device, { device });
  return instance.api;
}

/** Pull the rendered "Stale trace" line out of the report, if present. */
function staleLine(report: string): string | null {
  const line = report.split("\n").find((l) => l.includes("Stale trace"));
  return line ?? null;
}

describe("native-profiler freshness flagging — real analyze/render path", () => {
  let tempDir = "";
  let restoreTmpdir: () => void = () => {};

  beforeEach(async () => {
    // The analyze path's dependency gate resolves a real `adb` off PATH,
    // $ANDROID_HOME and the default SDK locations, so without priming these
    // tests pass only on a machine that has the Android SDK installed.
    __resetDepCacheForTests();
    __primeDepCacheForTests(["adb"]);
    runTpQueryMock.mockReset();
    routeCleanTrace();
    // Resolve the isolated dir off the REAL tmpdir before we redirect it.
    tempDir = await mkdtemp(join(tmpdir(), "argent-freshness-e2e-"));
    // getDebugDir() = join(os.tmpdir(), "argent-profiler-cwd"); profiler-load
    // resolves it dynamically, so redirect os.tmpdir() at our isolated dir. The
    // session_id .pftrace then lives under <tempDir>/argent-profiler-cwd/.
    restoreTmpdir = redirectTmpdir(tempDir);
  });

  afterEach(async () => {
    // Restore FIRST so the cleanup rm and any later suite resolve the real
    // tmpdir again — leaving it pointed at the (about-to-be-deleted) temp dir
    // breaks every subsequent os.tmpdir() consumer.
    restoreTmpdir();
    await rm(tempDir, { recursive: true, force: true });
    vi.clearAllMocks();
  });

  // Directory getDebugDir() resolves to once the tmpdir points at tempDir.
  function debugDir(): string {
    return join(tempDir, "argent-profiler-cwd");
  }

  /**
   * Write the .pftrace fixture (empty file — the stubbed engine tolerates it)
   * plus the REAL metadata sidecar carrying `wallClockStartMs`, then restore it
   * via the real profiler-load tool and run the real analyze tool. Returns the
   * rendered report.
   */
  async function loadThenAnalyze(wallClockStartMs: number | null): Promise<string> {
    const { mkdir } = await import("node:fs/promises");
    await mkdir(debugDir(), { recursive: true });
    const pftrace = join(debugDir(), `native-profiler-${SESSION_ID}.pftrace`);
    await writeFile(pftrace, "", "utf8");
    await writeAndroidNativeProfilerMetadata(pftrace, {
      platform: "android",
      appProcess: "com.example.app",
      wallClockStartMs,
    });

    const api = await buildAndroidSession();

    // Real restore: profiler-load reads the sidecar and sets api.wallClockStartMs.
    await profilerLoadTool.execute({ session: api } as never, {
      mode: "load_native",
      session_id: SESSION_ID,
      port: 8081,
      device_id: SERIAL,
    });

    // Real analyze: runs the pipeline (engine stubbed), then
    // formatTraceFreshness(api.wallClockStartMs, Date.now()) for real, threads
    // the note into the renderer.
    const result = await nativeProfilerAnalyzeTool.execute(
      { session: api } as never,
      { device_id: SERIAL },
      { artifacts: new ArtifactStore() } as never
    );
    return result.report;
  }

  it("a just-made capture (−2 min) is NEVER flagged stale", async () => {
    const report = await loadThenAnalyze(Date.now() - 2 * MIN);
    const line = staleLine(report);
    console.log(`[freshness E2E] −2 min  → ${line ?? "(no stale flag — FRESH)"}`);
    expect(line).toBeNull();
    expect(report).toContain("All clear");
  });

  it("a capture at the RECORDING_CAP_MS limit is still fresh (10-min cap < 30-min stale)", async () => {
    // The hard recording cap is 10 min; even a trace recorded right up to the
    // cap and analyzed instantly is well under the 30-min stale threshold.
    const report = await loadThenAnalyze(Date.now() - RECORDING_CAP_MS);
    const line = staleLine(report);
    console.log(`[freshness E2E] −RECORDING_CAP (10 min) → ${line ?? "(no stale flag — FRESH)"}`);
    expect(line).toBeNull();
  });

  it("the exact 30-min boundary IS flagged stale (ageMs === STALE_AFTER_MS)", async () => {
    const report = await loadThenAnalyze(Date.now() - 30 * MIN);
    const line = staleLine(report);
    console.log(`[freshness E2E] −30 min (boundary) → ${line}`);
    expect(line).toMatch(/Stale trace/);
    expect(line).toMatch(/30 minutes ago/);
  });

  it("a 45-min-old trace is flagged stale, in minutes", async () => {
    const report = await loadThenAnalyze(Date.now() - 45 * MIN);
    const line = staleLine(report);
    console.log(`[freshness E2E] −45 min → ${line}`);
    expect(line).toMatch(/Stale trace/);
    expect(line).toMatch(/45 minutes ago/);
  });

  it("a 3-hour-old trace is flagged stale, in hours", async () => {
    const report = await loadThenAnalyze(Date.now() - 3 * 60 * MIN);
    const line = staleLine(report);
    console.log(`[freshness E2E] −3 h → ${line}`);
    expect(line).toMatch(/Stale trace/);
    expect(line).toMatch(/3 hours ago/);
  });

  it("a 2-day-old trace is flagged stale, in days", async () => {
    const report = await loadThenAnalyze(Date.now() - 2 * 24 * 60 * MIN);
    const line = staleLine(report);
    console.log(`[freshness E2E] −2 d → ${line}`);
    expect(line).toMatch(/Stale trace/);
    expect(line).toMatch(/2 days ago/);
  });

  it("a sidecar with a MISSING wallClockStartMs is guarded (no flag, no NaN/Invalid Date)", async () => {
    const report = await loadThenAnalyze(null);
    const line = staleLine(report);
    console.log(`[freshness E2E] wallClockStartMs=null → ${line ?? "(no stale flag — guarded)"}`);
    expect(line).toBeNull();
    expect(report).not.toMatch(/NaN/);
    expect(report).not.toMatch(/Invalid Date/);
  });

  it("a non-finite wallClockStartMs (NaN) is guarded — never throws, never renders garbage", async () => {
    // The sidecar reader rejects non-number wallClockStartMs, so a NaN can only
    // reach analyze via an in-memory session (e.g. a future code path setting
    // it). Assert the guard at the analyze boundary directly with the same
    // engine stub in force.
    const api = await buildAndroidSession();
    const { mkdir } = await import("node:fs/promises");
    await mkdir(debugDir(), { recursive: true });
    const pftrace = join(debugDir(), `native-profiler-${SESSION_ID}.pftrace`);
    await writeFile(pftrace, "", "utf8");
    api.appProcess = "com.example.app";
    api.exportedFiles = { pftrace };
    api.wallClockStartMs = NaN;

    const result = await nativeProfilerAnalyzeTool.execute(
      { session: api } as never,
      { device_id: SERIAL },
      { artifacts: new ArtifactStore() } as never
    );
    console.log(
      `[freshness E2E] wallClockStartMs=NaN → ${staleLine(result.report) ?? "(no stale flag — guarded)"}`
    );
    expect(staleLine(result.report)).toBeNull();
    expect(result.report).not.toMatch(/NaN/);
    expect(result.report).not.toMatch(/Invalid Date/);

    api.wallClockStartMs = Infinity;
    const result2 = await nativeProfilerAnalyzeTool.execute(
      { session: api } as never,
      { device_id: SERIAL },
      { artifacts: new ArtifactStore() } as never
    );
    console.log(
      `[freshness E2E] wallClockStartMs=Infinity → ${staleLine(result2.report) ?? "(no stale flag — guarded)"}`
    );
    expect(staleLine(result2.report)).toBeNull();
    expect(result2.report).not.toMatch(/Invalid Date/);
  });
});

describe("Android profiler metadata sidecar — wallClockStartMs persistence round-trip", () => {
  let tempDir = "";

  beforeEach(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "argent-sidecar-"));
  });
  afterEach(async () => {
    await rm(tempDir, { recursive: true, force: true });
  });

  it("persists and restores a numeric wallClockStartMs verbatim", async () => {
    const pftrace = join(tempDir, "native-profiler-x.pftrace");
    const wall = 1_710_000_000_000;
    await writeAndroidNativeProfilerMetadata(pftrace, {
      platform: "android",
      appProcess: "com.example.app",
      wallClockStartMs: wall,
    });
    // Inspect the on-disk sidecar shape too — this is the contract profiler-load
    // and the device-side stop path both depend on.
    const raw = JSON.parse(await readFile(androidNativeProfilerMetadataPath(pftrace), "utf8"));
    expect(raw).toMatchObject({
      platform: "android",
      appProcess: "com.example.app",
      wallClockStartMs: wall,
    });

    const restored = await readAndroidNativeProfilerMetadata(pftrace);
    expect(restored).toEqual({
      platform: "android",
      appProcess: "com.example.app",
      wallClockStartMs: wall,
    });
  });

  it("persists and restores a null wallClockStartMs (unknown capture time)", async () => {
    const pftrace = join(tempDir, "native-profiler-y.pftrace");
    await writeAndroidNativeProfilerMetadata(pftrace, {
      platform: "android",
      appProcess: "com.example.app",
      wallClockStartMs: null,
    });
    const restored = await readAndroidNativeProfilerMetadata(pftrace);
    expect(restored?.wallClockStartMs).toBeNull();
  });

  it("returns null when the sidecar is absent (ENOENT, not a throw)", async () => {
    const pftrace = join(tempDir, "native-profiler-missing.pftrace");
    expect(await readAndroidNativeProfilerMetadata(pftrace)).toBeNull();
  });

  it("throws on a corrupt sidecar where wallClockStartMs is the wrong type", async () => {
    const pftrace = join(tempDir, "native-profiler-bad.pftrace");
    await writeFile(
      androidNativeProfilerMetadataPath(pftrace),
      JSON.stringify({
        platform: "android",
        appProcess: "com.example.app",
        wallClockStartMs: "nope",
      }),
      "utf8"
    );
    await expect(readAndroidNativeProfilerMetadata(pftrace)).rejects.toThrow(
      /Invalid Android profiler metadata/
    );
  });
});

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { promises as fs } from "fs";
import * as os from "os";
import * as path from "path";

// ---------------------------------------------------------------------------
// True end-to-end test for `profiler-load { mode: "list" }`.
//
// Unlike profiler-load-list.test.ts (which vi.mocks getDebugDir), this exercises
// the REAL getDebugDir(): it returns `join(os.tmpdir(), "argent-profiler-cwd")`.
// So we point the tmpdir at an isolated scratch dir per test and let the real
// code resolve the real on-disk path. Nothing in listSessions (the logic under
// test) is mocked.
//
// The `mode: "list"` execute path calls `listSessions(await getDebugDir())` and
// never touches `services`, so we drive it as execute({}, { mode: "list", ... }).
//
// Fixtures faithfully mirror what the writers put on disk:
//   Android (platforms/android.ts + session-metadata.ts):
//     native-profiler-<ts>.pftrace
//     native-profiler-<ts>.pftrace.metadata.json   { platform:"android", appProcess, wallClockStartMs }
//     native-profiler-<ts>-report.md               (written by native-profiler-analyze)
//   iOS (platforms/ios.ts + ios-profiler/render.ts deriveReportPath):
//     native-profiler-<ts>.trace                    (a directory in reality)
//     native-profiler-<ts>_raw_cpu.xml / _raw_hangs.xml / _raw_leaks.xml
//     native-profiler-<ts>-report.md
// Timestamp format on both platforms: YYYYMMDD-HHMMSS (15 chars).
// ---------------------------------------------------------------------------

let scratch = "";
let debugDir: string;
let restoreTmpdir: () => void = () => {};

// Imported once; it reads getDebugDir() lazily inside execute, so per-test
// tmpdir changes are honoured without re-importing.
import { profilerLoadTool } from "../../src/tools/profiler/query/profiler-load";
import { redirectTmpdir } from "../helpers/tmpdir-env";

async function runList(): Promise<string> {
  return (await profilerLoadTool.execute(
    {} as never,
    { mode: "list", device_id: "emulator-5554", port: 8081 } as never
  )) as string;
}

/** Faithful Android session on disk: pftrace + metadata sidecar + report. */
async function writeAndroidSession(
  ts: string,
  opts: { metadata?: boolean | string; report?: boolean | string } = {}
): Promise<void> {
  const pftrace = path.join(debugDir, `native-profiler-${ts}.pftrace`);
  // The real .pftrace is a binary perfetto blob; a non-empty byte string is a
  // faithful enough stand-in for a listing test (list never parses it).
  await fs.writeFile(pftrace, "\x0a\x00perfetto-trace-bytes");
  if (opts.metadata !== false) {
    const body =
      typeof opts.metadata === "string"
        ? opts.metadata
        : `${JSON.stringify(
            { platform: "android", appProcess: "com.example.app", wallClockStartMs: 1710000000000 },
            null,
            2
          )}\n`;
    await fs.writeFile(`${pftrace}.metadata.json`, body);
  }
  if (opts.report !== false) {
    const body =
      typeof opts.report === "string"
        ? opts.report
        : "# Native Profiler Report (Android)\n\nBottlenecks: 0\n";
    await fs.writeFile(path.join(debugDir, `native-profiler-${ts}-report.md`), body);
  }
}

/** Faithful iOS session on disk: .trace dir + raw XML exports + report. */
async function writeIosSession(
  ts: string,
  exports: { cpu?: boolean; hangs?: boolean; leaks?: boolean; report?: boolean | string } = {
    cpu: true,
  }
): Promise<void> {
  // The real .trace is a directory created by xctrace.
  await fs.mkdir(path.join(debugDir, `native-profiler-${ts}.trace`), { recursive: true });
  if (exports.cpu)
    await fs.writeFile(
      path.join(debugDir, `native-profiler-${ts}_raw_cpu.xml`),
      "<trace-query-result></trace-query-result>"
    );
  if (exports.hangs)
    await fs.writeFile(
      path.join(debugDir, `native-profiler-${ts}_raw_hangs.xml`),
      "<trace-query-result></trace-query-result>"
    );
  if (exports.leaks)
    await fs.writeFile(
      path.join(debugDir, `native-profiler-${ts}_raw_leaks.xml`),
      "<trace-query-result></trace-query-result>"
    );
  if (exports.report !== false) {
    const body =
      typeof exports.report === "string"
        ? exports.report
        : "# Native Profiler Report (iOS)\n\nHotspots: 0\n";
    await fs.writeFile(path.join(debugDir, `native-profiler-${ts}-report.md`), body);
  }
}

function countOccurrences(haystack: string, needle: string): number {
  return haystack.split(needle).length - 1;
}

describe("profiler-load list — E2E against real on-disk fixtures (no mocks)", () => {
  beforeEach(async () => {
    scratch = await fs.mkdtemp(path.join(os.tmpdir(), "argent-load-e2e-"));
    restoreTmpdir = redirectTmpdir(scratch);
    // Sanity: the real getDebugDir resolves under our scratch tmpdir.
    debugDir = path.join(os.tmpdir(), "argent-profiler-cwd");
    expect(debugDir.startsWith(scratch)).toBe(true);
    await fs.mkdir(debugDir, { recursive: true });
  });

  afterEach(async () => {
    restoreTmpdir();
    await fs.rm(scratch, { recursive: true, force: true });
  });

  // ---- Matrix case 1: mixed Android + iOS (the headline case) ----
  it("case 1 — mixed: each session under exactly one heading, correct columns & ordering", async () => {
    await writeIosSession("20260101-090000", { cpu: true, hangs: true, leaks: true, report: true });
    await writeAndroidSession("20260615-112028", { metadata: true, report: true });

    const out = await runList();
    // OBSERVABLE: print the rendered list for the headline case.
    console.log(
      "\n===== mixed (Android + iOS) — real list output =====\n" +
        out +
        "\n====================================================\n"
    );

    const iosIdx = out.indexOf("### Native Profiler Sessions (iOS)");
    const androidIdx = out.indexOf("### Native Profiler Sessions (Android)");
    expect(iosIdx).toBeGreaterThan(-1);
    expect(androidIdx).toBeGreaterThan(-1);
    // Section ordering: iOS heading comes before Android heading.
    expect(androidIdx).toBeGreaterThan(iosIdx);

    const iosSection = out.slice(iosIdx, androidIdx);
    const androidSection = out.slice(androidIdx);

    // iOS id only in iOS section; Android id only in Android section.
    expect(iosSection).toContain("20260101-090000");
    expect(iosSection).not.toContain("20260615-112028");
    expect(androidSection).toContain("20260615-112028");
    expect(androidSection).not.toContain("20260101-090000");

    // iOS columns: cpu+hangs+leaks+report present → "CPU, hangs, leaks, report".
    expect(iosSection).toContain("`20260101-090000` | CPU, hangs, leaks, report |");
    // Android columns: pftrace + report tag.
    expect(androidSection).toContain("`20260615-112028` | pftrace, report |");

    // Each session id appears exactly once across the whole output.
    expect(countOccurrences(out, "20260101-090000")).toBe(1);
    expect(countOccurrences(out, "20260615-112028")).toBe(1);
  });

  // ---- Matrix case 2: Android-only ----
  it("case 2 — Android-only: no iOS heading, session listed once", async () => {
    await writeAndroidSession("20260615-112028", { metadata: true, report: true });

    const out = await runList();
    expect(out).toContain("### Native Profiler Sessions (Android)");
    expect(out).not.toContain("### Native Profiler Sessions (iOS)");
    expect(countOccurrences(out, "20260615-112028")).toBe(1);
    expect(out).toContain("`20260615-112028` | pftrace, report |");
  });

  // ---- Matrix case 3: iOS-only ----
  it("case 3 — iOS-only: no Android heading", async () => {
    await writeIosSession("20260101-090000", {
      cpu: true,
      hangs: false,
      leaks: false,
      report: false,
    });

    const out = await runList();
    expect(out).toContain("### Native Profiler Sessions (iOS)");
    expect(out).not.toContain("### Native Profiler Sessions (Android)");
    expect(countOccurrences(out, "20260101-090000")).toBe(1);
    // Only CPU export → just "CPU".
    expect(out).toContain("`20260101-090000` | CPU |");
  });

  // ---- Matrix case 4: empty dir ----
  it("case 4 — empty debug dir: clean 'no sessions' output, no crash", async () => {
    const out = await runList();
    expect(out).toContain("No profiling sessions found");
    expect(out).not.toContain("### Native Profiler Sessions");
  });

  // ---- Matrix case 5: adversarial filenames — classify by REAL extension ----
  it("case 5 — adversarial: 'pftrace' substring in a .trace name is iOS; .pftrace is Android", async () => {
    // iOS session whose id literally contains the word 'pftrace' but the file
    // ends in .trace → must classify as iOS, NOT Android.
    await fs.mkdir(path.join(debugDir, "native-profiler-20260201-101010.trace"), {
      recursive: true,
    });
    await fs.writeFile(
      path.join(debugDir, "native-profiler-20260201-101010_raw_cpu.xml"),
      "<trace-query-result></trace-query-result>"
    );
    // Genuine Android .pftrace.
    await writeAndroidSession("20260202-202020", { metadata: true, report: false });

    const out = await runList();
    console.log(
      "\n===== adversarial extension classification — real list output =====\n" +
        out +
        "\n=================================================================\n"
    );

    const iosIdx = out.indexOf("(iOS)");
    const androidIdx = out.indexOf("(Android)");
    const iosSection = out.slice(iosIdx, androidIdx > iosIdx ? androidIdx : undefined);
    const androidSection = androidIdx > -1 ? out.slice(androidIdx) : "";

    // The 'pftrace'-named-but-.trace session is iOS only.
    expect(iosSection).toContain("20260201-101010");
    expect(androidSection).not.toContain("20260201-101010");
    // The real .pftrace is Android only.
    expect(androidSection).toContain("20260202-202020");
    expect(iosSection).not.toContain("20260202-202020");
  });

  it("case 5b — '...trace.pftrace' oddity classifies as Android (real extension .pftrace)", async () => {
    // A file whose name ends in `.trace.pftrace`: extension is .pftrace → Android.
    // We bypass writeAndroidSession to craft the odd name precisely.
    await fs.writeFile(
      path.join(debugDir, "native-profiler-20260303-303030.trace.pftrace"),
      "\x0a\x00bytes"
    );

    const out = await runList();
    console.log(
      "\n===== '.trace.pftrace' oddity — real list output =====\n" +
        out +
        "\n======================================================\n"
    );

    // Must be Android (ends in .pftrace), never iOS.
    expect(out).toContain("### Native Profiler Sessions (Android)");
    expect(out).not.toContain("### Native Profiler Sessions (iOS)");
    expect(out).toContain("`20260303-303030`");
    expect(countOccurrences(out, "20260303-303030")).toBe(1);
  });

  it("case 5c — an Android session with .pftrace + leftover -report.md never leaks into iOS (the regression)", async () => {
    // This is the exact scenario the PR fixes: the -report.md also matches the
    // native-profiler- prefix, so pre-fix it surfaced under BOTH headings.
    await writeAndroidSession("20260615-112028", { metadata: true, report: true });

    const out = await runList();
    expect(out).not.toContain("### Native Profiler Sessions (iOS)");
    expect(out).toContain("### Native Profiler Sessions (Android)");
    expect(countOccurrences(out, "20260615-112028")).toBe(1);
  });

  // ---- Matrix case 6: malformed / missing sidecars degrade gracefully ----
  it("case 6 — Android session with missing metadata & malformed report still classified, no throw", async () => {
    // No metadata sidecar, a malformed (non-markdown garbage) report present.
    await writeAndroidSession("20260404-040404", {
      metadata: false,
      report: "\x00\x01 not valid markdown \xff",
    });

    const out = await runList();
    expect(out).toContain("### Native Profiler Sessions (Android)");
    // listSessions does NOT read metadata/report contents for the list, so the
    // session is still classified and listed once with the report tag.
    expect(out).toContain("`20260404-040404` | pftrace, report |");
    expect(countOccurrences(out, "20260404-040404")).toBe(1);
  });

  it("case 6b — iOS session with malformed report & only leaks export degrades gracefully", async () => {
    await writeIosSession("20260505-050505", {
      cpu: false,
      hangs: false,
      leaks: true,
      report: "\x00 garbage report \xff",
    });

    const out = await runList();
    expect(out).toContain("### Native Profiler Sessions (iOS)");
    // Only leaks + report → "leaks, report".
    expect(out).toContain("`20260505-050505` | leaks, report |");
    expect(countOccurrences(out, "20260505-050505")).toBe(1);
  });

  // ---- Matrix case 7: co-timed iOS + Android under ONE session id ----
  it("case 7 — co-timed: ONE session id with both iOS and Android artifacts appears under BOTH headings (M1)", async () => {
    // iOS + Android captured in the same UTC second share one second-granular,
    // discriminator-free session id in the shared debug dir. Pre-fix the whole
    // group routed to Android and the iOS heading was HIDDEN (a visibility
    // regression). The session must now surface under BOTH headings, each
    // listing only its own artifacts.
    const ts = "20260615-112028";
    // iOS artifacts (xctrace .trace bundle + a raw CPU export).
    await fs.mkdir(path.join(debugDir, `native-profiler-${ts}.trace`), { recursive: true });
    await fs.writeFile(
      path.join(debugDir, `native-profiler-${ts}_raw_cpu.xml`),
      "<trace-query-result></trace-query-result>"
    );
    // Android artifacts (.pftrace + metadata sidecar).
    await fs.writeFile(path.join(debugDir, `native-profiler-${ts}.pftrace`), "\x0a\x00bytes");
    await fs.writeFile(
      path.join(debugDir, `native-profiler-${ts}.pftrace.metadata.json`),
      `${JSON.stringify(
        { platform: "android", appProcess: "com.example.app", wallClockStartMs: 1710000000000 },
        null,
        2
      )}\n`
    );
    // A single shared -report.md (matches the native prefix; both headings show it).
    await fs.writeFile(path.join(debugDir, `native-profiler-${ts}-report.md`), "# report\n");

    const out = await runList();
    console.log(
      "\n===== co-timed iOS+Android (M1) — real list output =====\n" +
        out +
        "\n========================================================\n"
    );

    const iosIdx = out.indexOf("### Native Profiler Sessions (iOS)");
    const androidIdx = out.indexOf("### Native Profiler Sessions (Android)");
    // BOTH headings present (pre-fix the iOS heading was missing entirely).
    expect(iosIdx).toBeGreaterThan(-1);
    expect(androidIdx).toBeGreaterThan(iosIdx);

    const iosSection = out.slice(iosIdx, androidIdx);
    const androidSection = out.slice(androidIdx);

    // The iOS row shows its own files (CPU + shared report), NOT pftrace.
    expect(iosSection).toContain(`\`${ts}\` | CPU, report |`);
    expect(iosSection).not.toContain("pftrace");
    // The Android row shows its own files (pftrace + shared report), NOT CPU.
    expect(androidSection).toContain(`\`${ts}\` | pftrace, report |`);
    expect(androidSection).not.toContain("CPU");

    // The session id appears under each heading exactly once (twice overall).
    expect(countOccurrences(out, ts)).toBe(2);
  });

  // ---- Matrix case 8: lone .pftrace.metadata.json (no bare .pftrace) ----
  it("case 8 — lone .pftrace.metadata.json (no bare .pftrace) classifies as Android, not iOS (L1)", async () => {
    // The metadata sidecar does NOT end in `.pftrace`, so the old
    // `.endsWith(".pftrace")` check misclassified a session whose only Android
    // marker was the sidecar as iOS. The `.pftrace.metadata.json` matcher fixes
    // this; the Android Files tag must omit the (absent) bare-pftrace tag.
    const ts = "20260707-070707";
    await fs.writeFile(
      path.join(debugDir, `native-profiler-${ts}.pftrace.metadata.json`),
      `${JSON.stringify({ platform: "android", appProcess: "com.example.app" })}\n`
    );
    await fs.writeFile(path.join(debugDir, `native-profiler-${ts}-report.md`), "# report\n");

    const out = await runList();
    console.log(
      "\n===== lone .pftrace.metadata.json (L1) — real list output =====\n" +
        out +
        "\n===============================================================\n"
    );

    expect(out).toContain("### Native Profiler Sessions (Android)");
    expect(out).not.toContain("### Native Profiler Sessions (iOS)");
    // No bare .pftrace on disk → the tag is just "report", never "pftrace".
    expect(out).toContain(`\`${ts}\` | report |`);
    expect(countOccurrences(out, ts)).toBe(1);
  });

  it("case 6c — debug dir missing entirely is recreated by getDebugDir, reports no sessions, no throw", async () => {
    // Remove the debug dir. Through the real execute() entry point, getDebugDir()
    // does `fs.mkdir(dir, { recursive: true })` BEFORE listSessions reads it, so
    // the directory always exists by the time readdir runs and we get the empty
    // "no sessions" message rather than the "_No debug directory found_" branch.
    await fs.rm(debugDir, { recursive: true, force: true });
    const out = await runList();
    expect(out).toContain("No profiling sessions found");
    // The dir was transparently recreated (empty) by getDebugDir.
    await expect(fs.readdir(debugDir)).resolves.toEqual([]);
  });
});

const electron = require('electron');
const path = require('path');
const url = require('url');
const fs = require('fs');
const { ipcMain } = require('electron');
const loadBalancer = require('electron-load-balancer');

const { app } = electron;
const { BrowserWindow, dialog } = electron;
const nativeImage = electron.nativeImage;

const scriptDir = 'scripts';

/**
 * Get the path to the requested Python script, specified by its name.
 * In dev mode, the path is just relative to the files in `background_tasks`.
 * For distribution, we bundle everything into an asar archive except for the
 * Python scripts. Otherwise, the Python interpreter cannot locate them.
 */
const getScriptPath = scriptName => {
  const appPath = app.getAppPath();
  if (process.env.DEV) {
    return path.join(appPath, scriptDir, scriptName);
  }
  return path
    .join(appPath, scriptDir, scriptName)
    .replace('app.asar', 'app.asar.unpacked');
};

if (process.env.DEV) {
  const {
    default: installExtension,
    REDUX_DEVTOOLS,
    REACT_DEVELOPER_TOOLS,
  } = require('electron-devtools-installer');

  app.whenReady().then(() => {
    installExtension(REDUX_DEVTOOLS).then(name =>
      console.log(`Added Extension:  ${name}`),
    );
    installExtension(REACT_DEVELOPER_TOOLS).then(name =>
      console.log(`Added Extension:  ${name}`),
    );
  });
}

const icon = nativeImage.createFromPath(path.join(__dirname, 'app_icon.png'));
let mainWindow;

function createWindow() {
  const startUrl = process.env.DEV
    ? 'http://localhost:3000'
    : url.format({
        pathname: path.join(__dirname, '/../build/index.html'),
        protocol: 'file:',
        slashes: true,
      });
  mainWindow = new BrowserWindow({
    show: false,
    icon,
    webPreferences: {
      nodeIntegration: true,
      enableRemoteModule: false,
    },
    minWidth: 500,
    minHeight: 300,
  });
  mainWindow.maximize();
  mainWindow.show();

  mainWindow.loadURL(startUrl);
  process.env.DEV && mainWindow.webContents.openDevTools();

  mainWindow.on('closed', function() {
    loadBalancer.stopAll();
    mainWindow = null;
  });
}

app.on('ready', createWindow);

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('activate', () => {
  if (mainWindow === null) {
    createWindow();
  }
});

